// Wedge (headquarters) squares 0,4,8,12,16,20 carry the six categories in
// order; every other square takes its category from its position in the
// six-category cycle. (A plain position%6 for the wedge squares too would
// only ever award Geography, History and Science & Nature wedges, so no one
// could ever collect all six.)
function catOf(p){var w=WEDGESQ.indexOf(p);return w>=0?w:p%6;}
function fresh(n){return {positions:Array(n).fill(0),wedges:Array.from({length:n},function(){return Array(6).fill(false);}),correct:Array(n).fill(0),turn:0,phase:"roll",die:0,qcat:-1,qidx:-1,asked:[[],[],[],[],[],[]],totalQ:0,streak:0,winner:-1,over:false,last_move:null};}
function legal(s){if(s.over)return[];if(s.phase==="roll")return[{type:"roll"}];return [0,1,2,3].map(function(c){return{type:"answer",choice:c};});}
function wcount(w){return w.filter(Boolean).length;}
function capWinner(s){var best=0;for(var i=1;i<s.positions.length;i++){var a=wcount(s.wedges[i]),b=wcount(s.wedges[best]);if(a>b||(a===b&&s.correct[i]>s.correct[best]))best=i;}return best;}
function finish(s,w){s.over=true;s.winner=w;}
function payout(s,ctx){const humans=ctx.players.filter(p=>p.kind==='human'&&p.active!==false),winner=ctx.players[s.winner];const recipients=winner&&winner.kind==='human'&&winner.active!==false?[winner]:humans;const out={};if(!recipients.length)return out;recipients.forEach((p,i)=>out[p.id]=Math.floor(ctx.pot/recipients.length)+(i<ctx.pot%recipients.length?1:0));return out;}
const game={
  newMatch(ctx){return {state:fresh(ctx.players.length),turn:[ctx.players[0].id]};},
  applyMove(state,id,move,ctx){
    if(state.over||ctx.players[state.turn].id!==id||!move||typeof move!=="object"||Array.isArray(move))throw new InvalidMove("Illegal move");
    const options=legal(state),keys=Object.keys(move);
    if(!options.some(m=>Object.keys(m).length===keys.length&&keys.every(k=>Object.prototype.hasOwnProperty.call(m,k)&&m[k]===move[k])))throw new InvalidMove("Illegal move");
    const s=JSON.parse(JSON.stringify(state)),seat=s.turn;
    if(move.type==="roll"){
      const fromSq=s.positions[seat];
      s.die=1+Math.floor(ctx.random()*6);
      s.positions[seat]=(s.positions[seat]+s.die)%24;
      s.last_move={kind:"move",seat:seat,piece_id:"tok_"+seat,roll:s.die,from_square:fromSq,to_square:s.positions[seat],from:{board:"track",position:{cell:String(fromSq)}},to:{board:"track",position:{cell:String(s.positions[seat])}}};
      const cat=catOf(s.positions[seat]);
      let avail=[];for(let i=0;i<BANK[cat].length;i++)if(s.asked[cat].indexOf(i)<0)avail.push(i);
      if(!avail.length){s.asked[cat]=[];avail=BANK[cat].map((_,i)=>i);}
      const pick=avail[Math.floor(ctx.random()*avail.length)];
      s.asked[cat].push(pick);s.qcat=cat;s.qidx=pick;s.phase="question";s.totalQ++;
    }else{
      const right=BANK[s.qcat][s.qidx][2];
      const acat=s.qcat,hadWedge=s.wedges[seat][acat];
      if(move.choice===right){
        s.correct[seat]++;s.streak++;
        if(s.wedges[seat].every(Boolean)){finish(s,seat);}
        else{
          // Wedge square: earn its wedge. Otherwise every second correct
          // answer in a row earns the question category's wedge as well.
          if(WEDGESQ.indexOf(s.positions[seat])>=0||s.streak%2===0)s.wedges[seat][s.qcat]=true;
          if(s.totalQ>=300)finish(s,capWinner(s));else{s.phase="roll";s.qcat=-1;s.qidx=-1;}
        }
      }else{
        s.streak=0;
        if(s.totalQ>=300)finish(s,capWinner(s));else{s.turn=(seat+1)%s.positions.length;s.phase="roll";s.qcat=-1;s.qidx=-1;}
      }
      s.last_move=(!hadWedge&&s.wedges[seat][acat])?{kind:"answer",seat:seat,wedge:{piece_id:"pip_"+seat+"_"+acat,category:acat}}:{kind:"answer",seat:seat};
    }
    return s.over?{state:s,turn:null,payouts:payout(s,ctx)}:{state:s,turn:[ctx.players[s.turn].id]};
  },
  viewFor(state,id,ctx){
    const s=JSON.parse(JSON.stringify(state));
    if(s.last_move===undefined)s.last_move=null;
    s.question=(!s.over&&s.phase==="question"&&s.qcat>=0)?{cat:s.qcat,category:CATS[s.qcat],q:BANK[s.qcat][s.qidx][0],options:BANK[s.qcat][s.qidx][1]}:null;
    s.legal=(!s.over&&id===ctx.players[s.turn].id)?legal(s):[];
    return s;
  },
  randomMove(s,id,ctx){const o=legal(s);return o[Math.floor(ctx.random()*o.length)];},
  computerMove(s,id,ctx){
    if(s.phase==="roll")return {type:"roll"};
    const right=BANK[s.qcat][s.qidx][2];
    if(ctx.random()<0.6)return {type:"answer",choice:right};
    const wrong=[];for(let i=0;i<4;i++)if(i!==right)wrong.push(i);
    return {type:"answer",choice:wrong[Math.floor(ctx.random()*wrong.length)]};
  }
};

