const SOURCE_STRINGS={"title": "Trivial Pursuit", "turn": "Player {n} to move", "finished": "Finished", "winner": "Player {n} wins", "roll": "Roll die", "phase_roll": "Roll the die to move your token", "phase_question": "{cat} question - choose an answer", "player_score": "Player {n}: {c} correct", "die": "Die: {n}", "server_invalid": "Illegal move"};
const CELLS=[[48, 36], [142, 36], [236, 36], [330, 36], [424, 36], [518, 36], [612, 36], [706, 36], [706, 98], [706, 160], [706, 222], [706, 284], [706, 346], [612, 346], [518, 346], [424, 346], [330, 346], [236, 346], [142, 346], [48, 346], [48, 222], [48, 160], [48, 98], [48, 36]];
const SHORT=["GEO","ENT","HIS","ART","SCI","SPO"];
var gameUI={
  reduce:function(message,localState){
    var m=message.type==="ui_event"?message.state_changed:message;
    var s=m.view||m.state;
    var strings=Object.assign({},SOURCE_STRINGS,m.strings||{});
    var t=function(k,a){a=a||{};return (strings[k]||k).replace(/\{(\w+)\}/g,function(_,x){return String(a[x]===undefined?"":a[x]);});};
    var active=m.status==="ongoing"&&!m.replay&&m.acting_for_player_index!==null&&m.acting_for_player_index!==undefined;
    var legal=active?(s.legal||[]):[];
    var pieces=[],controls=[],labels=[];
    labels.push({id:"title",text:t("title"),x:20,y:10,font_size:26});
    labels.push({id:"status",text:s.over?t("winner",{n:s.winner+1}):t("turn",{n:s.turn+1}),x:20,y:40,font_size:18});
    s.positions.forEach(function(pos,seat){
      var c=CELLS[pos],dx=(seat%2===0?-14:14),dy=(seat<2?-14:14);
      pieces.push({id:"tok_"+seat,type:"tok"+seat,board:"track",position:{x:c[0]+dx,y:c[1]+dy},text:String(seat+1),actions:[]});
    });
    pieces.push({id:"die",type:"die",board:"panel",position:{x:706,y:30},die_value:s.die||0,text:s.die?String(s.die):"-",actions:[]});
    labels.push({id:"die_label",text:t("die",{n:s.die||"-"}),x:636,y:446+62,font_size:15});
    s.wedges.forEach(function(w,seat){
      w.forEach(function(owned,cat){
        pieces.push({id:"pip_"+seat+"_"+cat,type:owned?"pip"+cat:"pip_empty",board:"panel",position:{x:262+cat*42,y:30+seat*38},text:owned?SHORT[cat]:"",actions:[]});
      });
      labels.push({id:"prow_"+seat,text:t("player_score",{n:seat+1,c:s.correct[seat]}),x:36,y:446+30+seat*38-9,font_size:16});
    });
    if(s.question){
      labels.push({id:"qcat",text:t("phase_question",{cat:s.question.category}),x:20,y:628,font_size:18});
      labels.push({id:"qtext",text:s.question.q,x:20,y:656,font_size:20});
    }else if(!s.over){
      labels.push({id:"qcat",text:t("phase_roll"),x:20,y:628,font_size:18});
    }
    if(s.over)labels.push({id:"fin",text:t("finished"),x:20,y:656,font_size:20});
    var keyOf=function(mv){return Object.keys(mv).map(function(k){return k+"_"+mv[k];}).join("_");};
    legal.forEach(function(mv){
      if(mv.type==="roll")controls.push({id:keyOf(mv),kind:"button",label:t("roll")});
      else controls.push({id:keyOf(mv),kind:"button",label:s.question?s.question.options[mv.choice]:""});
    });
    var out={scene:{pieces:pieces,targets:[],controls:controls,labels:labels},local_state:{}};
    if(message.type==="ui_event"&&active&&message.event.type==="tap"){
      var mv=legal.find(function(o){return keyOf(o)===message.event.id;});
      if(mv)out.make_move=mv;
    }
    return out;
  },
  getLastMoveAnimations:function(view,scene){
    if(!view||!Object.prototype.hasOwnProperty.call(view,"last_move"))return null;
    var mv=view.last_move;
    if(!mv)return [];
    var pieces=(scene&&scene.pieces)||[];
    var find=function(id){for(var i=0;i<pieces.length;i++)if(pieces[i].id===id)return pieces[i];return null;};
    if(mv.kind==="move"){
      var pawn=find(mv.piece_id||("tok_"+mv.seat));
      if(!pawn)return [];
      var fromSq=mv.from_square,roll=mv.roll;
      if(typeof fromSq!=="number"||typeof roll!=="number"||roll<1||roll>6)return [];
      var dx=(mv.seat%2===0?-14:14),dy=(mv.seat<2?-14:14);
      var path=[];
      for(var step=0;step<=roll;step++){var sq=(fromSq+step)%24,c=CELLS[sq];path.push({board:"track",position:{x:c[0]+dx,y:c[1]+dy}});}
      path[path.length-1]={board:pawn.board,position:{x:pawn.position.x,y:pawn.position.y}};
      return [{piece_id:pawn.id,duration_ms:Math.min(5000,roll*180),path:path}];
    }
    if(mv.kind==="answer"&&mv.wedge){
      var pip=find(mv.wedge.piece_id),tok=find("tok_"+mv.seat);
      if(!pip||!tok)return [];
      return [{piece_id:pip.id,duration_ms:700,path:[{board:tok.board,position:{x:tok.position.x,y:tok.position.y}},{board:pip.board,position:{x:pip.position.x,y:pip.position.y}}]}];
    }
    return [];
  }
};
